"""Build the separate eight-year training/two-year test analysis companion."""
from pathlib import Path
import nbformat as nbf

ROOT=Path(__file__).resolve().parents[1]
md=nbf.v4.new_markdown_cell;code=nbf.v4.new_code_cell
nb=nbf.v4.new_notebook()
nb.cells=[
md('# Ten-year Danish electricity methods pilot\n\n## tl;dr\nTrain on 2016–2023 and evaluate fixed models on 2024–2025. Four new methods supplement K-means + custom Apriori: GMM, DBSCAN, Random Forest classification, and histogram gradient boosting regression. The executed tables and report below contain the empirical conclusions. These models use realized generation/load, so this is not a day-ahead forecasting study.'),
md('## Context & Methods\nThe latest ten completed calendar years as of November 1, 2026 are 2016–2025. All preprocessing, high-price thresholds, model selection and rules use the eight training years only. No random train/test split is used.\n\n### Key Assumptions\n1. Before 2020, all solar is stored in the legacy self-consumption column; the model uses harmonized total solar.\n2. The 2020 negative estimated self-use values are floored at zero under the official metadata definition, with original values retained and every repair flagged. Strict no-repair and no-solar clustering sensitivities are provided.\n3. After October 1, 2025, four complete quarter prices are averaged per UTC hour. Hourly events and any-quarter events differ.\n4. The original pilot already examined 2024, so this is exploratory temporal evaluation rather than pristine confirmatory validation.'),
code("from pathlib import Path\nimport sys, subprocess, os, json\nimport pandas as pd\nfrom IPython.display import display, Markdown, Image\nROOT = Path.cwd()\nif not (ROOT / 'src').exists(): ROOT = ROOT.parent\nassert (ROOT / 'scripts/run_decade.py').exists()\nRESULTS = ROOT / 'results/decade'\n# True repeats model fitting from the included official input cache.\n# False loads the published, executed results for quick inspection.\nRERUN_ANALYSIS = False"),
md('## Data\nSource: Energinet Energi Data Service, CC BY 4.0. [Settlement metadata](https://api.energidataservice.dk/meta/dataset/ProductionConsumptionSettlement), [historical hourly prices](https://api.energidataservice.dk/meta/dataset/Elspotprices), [quarter-hour prices](https://api.energidataservice.dk/meta/dataset/DayAheadPrices). Data, raw response envelopes and metadata are included; see data/decade/README.md. No network access is needed after installing dependencies.'),
code("if RERUN_ANALYSIS:\n    environment = dict(os.environ, PYTHONIOENCODING='utf-8')\n    result = subprocess.run([sys.executable, str(ROOT/'scripts/run_decade.py'), '--offline'], cwd=ROOT, env=environment, capture_output=True, text=True, encoding='utf-8')\n    if result.returncode: raise RuntimeError(result.stdout[-3000:] + result.stderr[-3000:])\n    print('Full offline model fitting completed.')\nelse:\n    assert (RESULTS/'run_manifest.json').exists(), 'Run scripts/run_decade.py --offline first'\n    print('Loading published results; set RERUN_ANALYSIS=True to refit.')\ncoverage = pd.read_csv(RESULTS/'coverage.csv')\ndisplay(coverage.groupby(['source','area'])[['expected','observed','missing','null_cells']].sum())\ndisplay(pd.read_csv(RESULTS/'usable_coverage.csv'))"),
md('### Frozen protocol and historical repairs'),
code("protocol = json.loads((RESULTS/'frozen_protocol.json').read_text())\nprint('Training years:', protocol['training_years'])\nprint('Test years:', protocol['test_years'])\nprint('2020 solar estimate repairs:', protocol['training_solar_repairs'])\nprint('High-price thresholds (EUR/MWh):', protocol['high_price_thresholds_eur_mwh'])\ndisplay(pd.read_csv(RESULTS/'annual_profiles.csv'))\nprint('Price transition:', json.loads((RESULTS/'price_transition.json').read_text()))"),
md('## Results\n### Event rates through time\nHigh-price thresholds are fixed at the pooled eight-year area 95th percentiles, not recalculated for each test year.'),
code("display(Image(filename=str(RESULTS/'figures/yearly_events.png')))\ndisplay(pd.read_csv(RESULTS/'event_rates.csv'))"),
md('### Clustering and distribution drift\nK-means and GMM fit all eight training years. DBSCAN fits a bounded stratified sample from every training year/area; its frozen nearest-core adapter leaves out-of-neighborhood points as noise. Cluster IDs have meaning only within each method.'),
code("display(Image(filename=str(RESULTS/'figures/clusters_and_drift.png')))\ndisplay(pd.read_csv(RESULTS/'cluster_metrics.csv'))\ndisplay(pd.read_csv(RESULTS/'additional_clustering_candidates.csv'))"),
md('### Classification: probability quality and rare-event discrimination\nCompare energy+calendar models with calendar-only models of the same family. Brier is lower-is-better; average precision should be compared with event prevalence. Scores are also separated by test year and price area.'),
code("display(Image(filename=str(RESULTS/'figures/classification_comparison.png')))\nclassification = pd.read_csv(RESULTS/'classification_metrics.csv')\ndisplay(classification[(classification.test_year=='2024-2025') & (classification.area=='both')][['method','features','event','n','events','base_rate','brier','average_precision','roc_auc']])\ndisplay(classification[(classification.method=='random_forest') & (classification.area=='both')][['features','event','test_year','brier','average_precision']])"),
md('### Price regression\nMAE and RMSE are EUR/MWh. The boosting model has fixed hyperparameters with no random internal validation or holdout tuning.'),
code("display(Image(filename=str(RESULTS/'figures/regression_comparison.png')))\nregression = pd.read_csv(RESULTS/'regression_metrics.csv')\ndisplay(regression[regression.area=='both'])\ndisplay(pd.read_csv(RESULTS/'paired_improvement_intervals.csv'))"),
md('### Apriori transfer and uncertainty\nRules are mined only from predictor baskets, selected on training counts and lift, and then frozen. Exploratory intervals resample consecutive seven-day blocks synchronously across areas.'),
code("display(Image(filename=str(RESULTS/'figures/frozen_rules.png')))\nrules = pd.read_csv(RESULTS/'selected_rules.csv')\ndisplay(rules[['method','event','antecedent','train_n','train_events','train_lift','test_n','test_events','test_lift','ci_low','ci_high','test_small_sample']])\ndisplay(pd.read_csv(RESULTS/'rule_by_test_year.csv'))"),
md('### Solar-definition and correction sensitivities\nThe primary target definitions and test population remain fixed. One sensitivity removes solar; another fits the clustering only on rows that never required a negative-estimate correction. No hidden zero imputation of missing observations is used.'),
code("sensitivity = pd.read_csv(RESULTS/'solar_break_sensitivity.csv')\ndisplay(sensitivity[(sensitivity.test_year=='2024-2025') & (sensitivity.area=='both')])"),
md('## Takeaways\nThe report below is generated from the executed study. Read yearly/area scores, rare-event denominators, historical corrections and paired intervals before interpreting a pooled winner.'),
code("display(Markdown((RESULTS/'pilot_findings.md').read_text(encoding='utf-8')))"),
]
nb.metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.10'}}
nbf.validate(nb)
nbf.write(nb,ROOT/'notebooks/energy_price_decade.ipynb')
print('Created and validated notebooks/energy_price_decade.ipynb')
